"""Generate JSON Schemas and TypeScript types from canonical enums (IMP-0101).

Single source of truth: packages/py/contracts/src/trading_contracts/enums.py.
Outputs (deterministic, no timestamps, LF newlines):

- packages/schemas/json/enums/<snake_name>.schema.json  (one per enum)
- packages/ts/contracts-generated/src/enums.ts          (all enums)

Modes:
    uv run python scripts/generate_contracts.py           # write files
    uv run python scripts/generate_contracts.py --check   # fail on drift

--check fails when any generated file is missing, differs byte-for-byte from
the rendered output, or when a stray *.schema.json exists in the enums schema
directory. Exit code 0 means no drift.
"""

import argparse
import json
import re
import sys
from enum import StrEnum
from pathlib import Path

from trading_contracts.enums import CANONICAL_ENUMS, SCHEMA_VERSION

REPO_ROOT = Path(__file__).resolve().parents[1]
SCHEMA_DIR = REPO_ROOT / "packages" / "schemas" / "json" / "enums"
TS_FILE = REPO_ROOT / "packages" / "ts" / "contracts-generated" / "src" / "enums.ts"

GENERATED_HEADER = "GENERATED FILE — DO NOT EDIT"


def snake_name(enum_class: type[StrEnum]) -> str:
    return re.sub(r"(?<!^)(?=[A-Z])", "_", enum_class.__name__).lower()


def screaming_name(enum_class: type[StrEnum]) -> str:
    return snake_name(enum_class).upper()


def first_docstring_line(enum_class: type[StrEnum]) -> str:
    doc = enum_class.__doc__ or enum_class.__name__
    return doc.strip().splitlines()[0].strip()


def render_schema(enum_class: type[StrEnum]) -> str:
    schema = {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "$id": f"trading-system/enums/{snake_name(enum_class)}/{SCHEMA_VERSION}",
        "title": enum_class.__name__,
        "description": first_docstring_line(enum_class),
        "type": "string",
        "enum": [member.value for member in enum_class],
        "x-generated-by": "scripts/generate_contracts.py",
        "x-generated-note": GENERATED_HEADER,
    }
    return json.dumps(schema, ensure_ascii=False, indent=2) + "\n"


def render_typescript() -> str:
    lines: list[str] = [
        f"// {GENERATED_HEADER}.",
        "// Generated by scripts/generate_contracts.py from trading_contracts.enums",
        "// (single source of truth). Values are canonical per the baseline documents.",
        "",
    ]
    for enum_class in CANONICAL_ENUMS:
        name = enum_class.__name__
        values_const = f"{screaming_name(enum_class)}_VALUES"
        lines.append(f"/** {first_docstring_line(enum_class)} */")
        lines.append(f"export const {name} = {{")
        for member in enum_class:
            lines.append(f'  {member.name}: "{member.value}",')
        lines.append("} as const;")
        lines.append(f"export type {name} = (typeof {name})[keyof typeof {name}];")
        lines.append(
            f"export const {values_const}: readonly {name}[] = Object.freeze("
            f"Object.values({name}));"
        )
        lines.append(f"export function is{name}(value: string): value is {name} {{")
        lines.append(f"  return ({values_const} as readonly string[]).includes(value);")
        lines.append("}")
        lines.append("")
    return "\n".join(lines)


def expected_files() -> dict[Path, str]:
    files: dict[Path, str] = {
        SCHEMA_DIR / f"{snake_name(enum_class)}.schema.json": render_schema(enum_class)
        for enum_class in CANONICAL_ENUMS
    }
    files[TS_FILE] = render_typescript()
    return files


def write_files() -> list[Path]:
    written: list[Path] = []
    for path, content in expected_files().items():
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.is_file() or path.read_text(encoding="utf-8") != content:
            with path.open("w", encoding="utf-8", newline="\n") as handle:
                handle.write(content)
            written.append(path)
    return written


def check_files() -> list[str]:
    problems: list[str] = []
    expected = expected_files()
    for path, content in expected.items():
        rel = path.relative_to(REPO_ROOT).as_posix()
        if not path.is_file():
            problems.append(f"missing-generated: {rel}")
        elif path.read_text(encoding="utf-8") != content:
            problems.append(f"drift: {rel} differs from the canonical source")
    if SCHEMA_DIR.is_dir():
        expected_schemas = {path for path in expected if path.suffix == ".json"}
        for stray in sorted(SCHEMA_DIR.glob("*.schema.json")):
            if stray not in expected_schemas:
                rel = stray.relative_to(REPO_ROOT).as_posix()
                problems.append(f"stray-generated: {rel} has no canonical enum")
    return problems


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check",
        action="store_true",
        help="verify generated files match the canonical source; write nothing",
    )
    args = parser.parse_args(argv[1:])

    duplicate_free = all(
        len({member.value for member in enum_class}) == len(list(enum_class))
        for enum_class in CANONICAL_ENUMS
    )
    if not duplicate_free:
        print("FAIL: duplicate values inside a canonical enum.")
        return 1

    if args.check:
        problems = check_files()
        for problem in problems:
            print(problem)
        if problems:
            print(f"FAIL: {len(problems)} contract drift problem(s).")
            return 1
        print("OK: generated contracts match the canonical source.")
        return 0

    written = write_files()
    for path in written:
        print(f"WROTE: {path.relative_to(REPO_ROOT).as_posix()}")
    print(f"OK: {len(written)} file(s) updated; generation is idempotent.")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
